E1 — PARÉNTESIS BALANCEADOS (stack)
  def balanceado(s):
      pila, parejas = [], {")": "(", "]": "[", "}": "{"}
      for c in s:
          if c in "([{": pila.append(c)
          elif c in ")]}":
              if not pila or pila.pop() != parejas[c]: return False
      return not pila
