E3 — TWO SUM (dict = evitar O(n²))
  def two_sum(nums, target):
      vistos = {}
      for i, n in enumerate(nums):
          if target - n in vistos: return [vistos[target - n], i]
          vistos[n] = i
E4 — INVERTIR LISTA O(n) SIN AYUDAS (dos punteros)
  def invertir(a):
      izq, der = 0, len(a) - 1
      while izq < der:
          a[izq], a[der] = a[der], a[izq]
          izq += 1; der -= 1

